// Author: MiYu. Deferred integration consumers for source channel schedules, reentrancy and independent ground lifetimes.
#include "session.h"
#include "setup.h"
#include "order_ids.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_channel_tests <data-root> <generated-channel-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession s(jass::Module::compile(jass::Program::read(archives)),info);s.attachWorld(std::move(world));s.audioMuted(true);s.configure();PlayerSetup setup(info,s.config());s.applySetup(setup);s.startMain();auto& vm=s.runtime();
        auto check=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto real=[](float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));};auto number=[](jass::Real v){return std::bit_cast<float>(v.bits());};auto code=[&](const char* id){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(id)));};auto bounds=s.world()->bounds();auto x=bounds.minX.add(bounds.maxX).divide(jass::Real::fromInteger(2)),y=bounds.minY.add(bounds.maxY).divide(jass::Real::fromInteger(2));
        vm.invoke("FogEnable",std::array{vm.boolean(false)});vm.invoke("FogMaskEnable",std::array{vm.boolean(false)});
        auto create=[&](unsigned owner,const char* type,float offset){auto h=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),code(type),vm.real(x.add(real(offset))),vm.real(y),vm.real(real(270))});vm.invoke("SetUnitPathing",std::array{h,vm.boolean(false)});auto u=s.units().at(h.bits);u->healthRegen=u->manaRegen=0;u->acquireRange={};u->maxLife=real(50000);u->life=u->maxLife;s.stopUnit(h.bits);return h;};
        auto caster=create(0,"Hpal",0),ally=create(0,"hfoo",100),victim=create(1,"hfoo",150),building=create(1,"hhou",250);auto c=s.units().at(caster.bits),a=s.units().at(ally.bits),v=s.units().at(victim.bits),b=s.units().at(building.bits);c->mana=c->maxMana=real(100000);vm.invoke("ProbeCaster",std::array{caster});vm.invoke("ProbeRegister");
        auto target=[&](const char* ability,jass::Value to){vm.invoke("ProbeTarget",std::array{to,code(ability)});};auto none=[&](const char* ability){target(ability,vm.handle("unit",0));};auto add=[&](const char* ability){check(vm.invoke("UnitAddAbility",std::array{caster,code(ability)}).bits!=0,"Source ability add failed");};auto reset=[&]{s.stopUnit(caster.bits);vm.invoke("UnitResetCooldown",std::array{caster});c->mana=c->maxMana;};auto point=WorldPoint{v->x,v->y};
        add("AHbz");auto& blizzard=s.spellInfo(ObjectData::code("AHbz"),1);check(blizzard.channelled && blizzard.pulses==6 && blizzard.shards==6 && blizzard.amount==30 && blizzard.period==1 && blizzard.maxDamage==150,"Blizzard source fields differ");none("AHbz");auto life=number(v->life),friendly=number(a->life);auto finish=vm.global("probe_finish").bits;check(s.castSpellAt(caster.bits,ObjectData::code("AHbz"),point),"Blizzard order rejected");s.advance(.75);check(c->cast && c->cast->phase==CastOrder::Phase::Channel && number(v->life)==life,"Blizzard did not wait for first wave");s.advance(1);check(number(v->life)<life && number(a->life)<friendly && vm.global("probe_finish").bits==finish,"Blizzard pulse/relationship/finish differs");auto end=vm.global("probe_end").bits;check(s.stopUnit(caster.bits),"Channel stop rejected");life=number(v->life);s.advance(2);check(!c->cast && number(v->life)==life && vm.global("probe_finish").bits==finish && vm.global("probe_end").bits==end+1,"Interrupted channel kept pulsing or fired FINISH");reset();
        none("AHbz");check(s.castSpellAt(caster.bits,ObjectData::code("AHbz"),point),"Blizzard recast rejected");s.advance(7);check(!c->cast && vm.global("probe_finish").bits==finish+1,"Source wave count did not complete channel");reset();
        add("AEtq");none("AEtq");a->life=real(100);life=number(v->life);check(s.castSpell(caster.bits,ObjectData::code("AEtq")),"Tranquility rejected");s.advance(2);check(number(a->life)>=120 && number(v->life)==life && a->buffs.contains(ObjectData::code("AEtr")) && a->buffs.at(ObjectData::code("AEtr")).positive,"Tranquility did not heal allies with positive visual state");reset();
        add("AEsf");none("AEsf");life=number(v->life);friendly=number(a->life);auto buildingLife=number(b->life);check(s.castSpell(caster.bits,ObjectData::code("AEsf")),"Starfall rejected");s.advance(2.25);check(number(v->life)<life && number(a->life)==friendly && number(b->life)<buildingLife && buildingLife-number(b->life)<50,"Starfall target/building factor missing");reset();
        add("AUdd");none("AUdd");vm.invoke("UnitAddAbility",std::array{victim,code("Amim")});life=number(v->life);check(s.castSpellAt(caster.bits,ObjectData::code("AUdd"),point),"Death and Decay rejected");s.advance(2);check(life-number(v->life)>=1999 && c->cast,"Death and Decay percentage/universal pulse missing");reset();vm.invoke("UnitRemoveAbility",std::array{victim,code("Amim")});
        for(auto id:{"A0CN","A0CU","A0CP","A0CE","A0CH"})add(id);check(s.spellInfo(ObjectData::code("A0CE"),1).targeting==SpellTargeting::Either && s.spellInfo(ObjectData::code("A0CP"),1).order==orderId("curse"),"Custom Channel object fields/base order missing");auto buttons=s.abilityCommands(caster.bits,0);check(std::none_of(buttons.begin(),buttons.end(),[](auto& b){return b.type==ObjectData::code("A0CH");}) && std::any_of(buttons.begin(),buttons.end(),[](auto& b){return b.type==ObjectData::code("A0CN");}),"Channel visible option not consumed");
        none("A0CN");finish=vm.global("probe_finish").bits;check(s.castSpell(caster.bits,ObjectData::code("A0CN")),"Immediate Channel rejected");s.advance(.75);check(c->cast && c->cast->phase==CastOrder::Phase::Channel && !s.castSpell(caster.bits,ObjectData::code("AEtq")),"Disable other abilities did not affect native cast");buttons=s.abilityCommands(caster.bits,0);check(std::any_of(buttons.begin(),buttons.end(),[](auto& b){return b.type==ObjectData::code("AEtq") && !b.enabled;}),"Disable other abilities missing in UI");vm.invoke("ProbePauseFinish",std::array{vm.boolean(true)});s.advance(.5);check(!c->cast && c->paused && vm.global("probe_finish").bits==finish+1,"FINISH pause retained completed cast");s.advance(.5);check(vm.global("probe_finish").bits==finish+1,"FINISH repeated after reentrant pause");vm.invoke("ProbePauseFinish",std::array{vm.boolean(false)});vm.invoke("PauseUnit",std::array{caster,vm.boolean(false)});reset();
        vm.invoke("UnitRemoveAbility",std::array{caster,code("A0CN")});vm.invoke("UnitRemoveAbility",std::array{caster,code("A0CH")});target("A0CU",victim);vm.invoke("UnitAddAbility",std::array{victim,code("Amim")});check(s.castOrder(caster.bits,orderId("cripple"),victim.bits),"Physical Channel unit/base order rejected immune target");s.advance(.75);check(c->cast && c->cast->target==victim.bits && c->cast->spell.targeting==SpellTargeting::Unit,"Channel unit context missing");reset();vm.invoke("UnitRemoveAbility",std::array{victim,code("Amim")});vm.invoke("UnitRemoveAbility",std::array{caster,code("A0CU")});
        none("A0CP");check(s.castPointOrder(caster.bits,orderId("curse"),point),"Point Channel/base order rejected");s.advance(.75);check(c->cast && c->cast->point.x.bits()==point.x.bits(),"Point Channel context missing");reset();vm.invoke("UnitRemoveAbility",std::array{caster,code("A0CP")});target("A0CE",victim);check(s.castSpell(caster.bits,ObjectData::code("A0CE"),victim.bits),"Either Channel rejected unit");s.advance(.75);check(c->cast && c->cast->spell.targeting==SpellTargeting::Unit,"Either did not retain actual unit mode");reset();none("A0CE");check(s.castSpellAt(caster.bits,ObjectData::code("A0CE"),point),"Either Channel rejected point");s.advance(.75);check(c->cast && c->cast->spell.targeting==SpellTargeting::Point,"Either did not retain actual point mode");reset();
        none("AHbz");vm.invoke("ProbeStopEffect",std::array{vm.boolean(true)});life=number(v->life);check(s.castSpellAt(caster.bits,ObjectData::code("AHbz"),point),"EFFECT interruption setup failed");s.advance(2);check(!c->cast && number(v->life)==life,"EFFECT reentrant stop still started channel");vm.invoke("ProbeStopEffect",std::array{vm.boolean(false)});reset();
        add("AHfs");none("AHfs");auto& flame=s.spellInfo(ObjectData::code("AHfs"),1);check(flame.fullTime==2.67f && flame.duration==9 && flame.extraDamage==4,"Flame Strike source schedule differs");life=number(v->life);check(s.castSpellAt(caster.bits,ObjectData::code("AHfs"),point),"Flame Strike rejected");s.advance(.75);check(!s.groundSpells().empty() && number(v->life)==life,"Ground effect did not wait for source delay");reset();s.advance(2);check(number(v->life)<life && !s.groundSpells().empty(),"Released ground spell stopped with caster");vm.invoke("KillUnit",std::array{caster});life=number(v->life);s.advance(1);check(number(v->life)<life,"Caster death stopped released ground effect");s.advance(10);check(s.groundSpells().empty(),"Ground effect exceeded total source duration");
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS channel consumers: source schedules, interruption, independent ground damage, target modes and reentrant events\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
